import csv
import json

import numpy as np
import stan


STAN_CODE = r"""
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X);
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

model {
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                    + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);

  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                      + diag_matrix(rep_vector(square(sigma), N));
    matrix[N, N] L_K = cholesky_decompose(K);
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
"""


DATA_PATH = "/app"


def load_data():
    with open(f"{DATA_PATH}/meta_public.json", encoding="utf-8") as metadata_file:
        metadata = json.load(metadata_file)

    train_x = np.loadtxt(f"{DATA_PATH}/train_X.csv", delimiter=",", skiprows=1)
    train_y = np.loadtxt(f"{DATA_PATH}/train_y.csv", delimiter=",", skiprows=1)
    test_x = np.loadtxt(f"{DATA_PATH}/test_X.csv", delimiter=",", skiprows=1)

    if train_x.ndim == 1:
        train_x = train_x.reshape(1, -1)
    if test_x.ndim == 1:
        test_x = test_x.reshape(1, -1)
    train_y = np.atleast_1d(train_y)

    p = int(metadata["P"])
    jitter = float(metadata["jitter"])
    n = train_x.shape[0]
    d = train_x.shape[1]
    n_new = test_x.shape[0]

    h = np.column_stack((np.ones(n), train_x[:, 0], train_x[:, 1]))
    h_new = np.column_stack((np.ones(n_new), test_x[:, 0], test_x[:, 1]))

    if h.shape[1] != p or h_new.shape[1] != p:
        raise ValueError(f"Expected P={p} regression columns, got {h.shape[1]}")

    return {
        "N": n,
        "D": d,
        "X": train_x,
        "P": p,
        "H": h,
        "y": train_y,
        "jitter": jitter,
        "N_new": n_new,
        "X_new": test_x,
        "H_new": h_new,
    }


def write_numeric_csv(path, values):
    values = np.asarray(values, dtype=float).reshape(-1)
    with open(path, "w", newline="", encoding="utf-8") as output_file:
        writer = csv.writer(output_file, lineterminator="\n")
        for value in values:
            writer.writerow([repr(float(value))])


def main():
    data = load_data()

    posterior = stan.build(STAN_CODE, data=data, random_seed=1)
    fit = posterior.sample(
        num_chains=4,
        num_warmup=1000,
        num_samples=1000,
        num_thin=2,
        save_warmup=False,
        refresh=200,
        init_radius=0.1,
        delta=0.93,
        max_depth=14,
        gamma=0.05,
        kappa=0.75,
        t0=10,
        init_buffer=100,
        term_buffer=50,
        window=25,
    )

    alpha_mean = np.mean(fit["alpha"])
    sigma_mean = np.mean(fit["sigma"])
    rho_mean = np.mean(fit["rho"], axis=1)
    beta_mean = np.mean(fit["beta"], axis=1)

    write_numeric_csv(f"{DATA_PATH}/alpha_est.csv", [alpha_mean])
    write_numeric_csv(f"{DATA_PATH}/sigma_est.csv", [sigma_mean])
    write_numeric_csv(f"{DATA_PATH}/rho_est.csv", rho_mean)
    write_numeric_csv(f"{DATA_PATH}/beta_est.csv", beta_mean)


if __name__ == "__main__":
    main()

